      { id: "b04_113_05", german: "braun", arabic: "\u0628\u0646\u064A (\u0644\u0648\u0646 \u0634\u0639\u0631 \u0643\u0633\u062A\u0646\u0627\u0626\u064A \u0623\u0648 \u062F\u0627\u0643\u0646)", emoji: "\u{1F9D2}", exampleSentenceGerman: "Er hat tiefbraune Haare und braune Augen.", exampleSentenceArabic: "\u0644\u062F\u064A\u0647 \u0634\u0639\u0631 \u0628\u0646\u064A \u062F\u0627\u0643\u0646 \u0648\u0639\u064A\u0646\u0627\u0646 \u0628\u0646\u064A\u062A\u0627\u0646.", missingLetterWord: "br_un", sentence4Elements: ["Braune", "Locken", "umrahmen", "sein fr\xF6hliches Kindergesicht."] },
      { id: "b04_113_06", german: "kurz", arabic: "\u0642\u0635\u064A\u0631 (\u062A\u0633\u0631\u064A\u062D\u0629 \u0634\u0639\u0631 \u0639\u0645\u0644\u064A\u0629)", emoji: "\u{1F466}", exampleSentenceGerman: "Im hei\xDFen Sommer schneidet er die Haare kurz.", exampleSentenceArabic: "\u0641\u064A \u0627\u0644\u0635\u064A\u0641 \u0627\u0644\u062D\u0627\u0631 \u064A\u0642\u0635 \u0634\u0639\u0631\u0647 \u0642\u0635\u064A\u0631\u0627\u064B.", missingLetterWord: "k_rz", sentence4Elements: ["Kurze", "Haare", "trocknen", "nach dem Schwimmen blitzschnell."] },
      { id: "b04_113_07", german: "lang", arabic: "\u0637\u0648\u064A\u0644 \u064A\u0646\u0633\u062F\u0644 \u0639\u0644\u0649 \u0627\u0644\u0623\u0643\u062A\u0627\u0641", emoji: "\u{1F467}", exampleSentenceGerman: "Ihre langen Haare reichen bis zum R\xFCcken.", exampleSentenceArabic: "\u0634\u0639\u0631\u0647\u0627 \u0627\u0644\u0637\u0648\u064A\u0644 \u064A\u0635\u0644 \u062D\u062A\u0649 \u0638\u0647\u0631\u0647\u0627.", missingLetterWord: "l_ng", sentence4Elements: ["Lange", "Haare", "kann", "man zu sch\xF6nen Z\xF6pfen flechten."] },
      { id: "b04_113_08", german: "der Zopf", arabic: "\u0627\u0644\u0636\u0641\u064A\u0631\u0629 / \u0630\u064A\u0644 \u0627\u0644\u062D\u0635\u0627\u0646", article: "der", plural: "die Z\xF6pfe", emoji: "\u{1F471}\u200D\u2640\uFE0F", exampleSentenceGerman: "Mama flicht ihr morgens einen h\xFCbschen Zopf.", exampleSentenceArabic: "\u062A\u062C\u062F\u0644 \u0644\u0647\u0627 \u0623\u0645\u0647\u0627 \u0635\u0628\u0627\u062D\u0627\u064B \u0636\u0641\u064A\u0631\u0629 \u062C\u0645\u064A\u0644\u0629 \u0648\u0645\u0631\u062A\u0628\u0629.", missingLetterWord: "der Z_pf", sentence4Elements: ["Ein", "bunter", "Zopf", "schwingt bei jedem Sprung hin und her."] },
      { id: "b04_113_09", german: "die Haarspange", arabic: "\u0645\u0634\u0628\u0643 \u0627\u0644\u0634\u0639\u0631 (\u0627\u0644\u062A\u0648\u0643\u0629/\u0627\u0644\u0628\u0646\u0633\u0629)", article: "die", plural: "die Haarspangen", emoji: "\u{1F380}", exampleSentenceGerman: "Eine glitzernde Spange h\xE4lt die Haare aus dem Gesicht.", exampleSentenceArabic: "\u0645\u0634\u0628\u0643 \u0634\u0639\u0631 \u0644\u0627\u0645\u0639 \u064A\u0628\u0639\u062F \u0627\u0644\u0634\u0639\u0631 \u0639\u0646 \u0627\u0644\u0648\u062C\u0647.", missingLetterWord: "H_arspange", sentence4Elements: ["Die", "Haarspange", "funkelt", "wie ein kleiner Stern."] },
      { id: "b04_113_10", german: "die B\xFCrste", arabic: "\u0641\u0631\u0634\u0627\u0629 \u0627\u0644\u0634\u0639\u0631 \u0644\u0641\u0643 \u0627\u0644\u062A\u0634\u0627\u0628\u0643", article: "die", plural: "die B\xFCrsten", emoji: "\u{1FAAE}", exampleSentenceGerman: "Mit der weichen B\xFCrste k\xE4mme ich sanft die Knoten aus.", exampleSentenceArabic: "\u0628\u0627\u0644\u0641\u0631\u0634\u0627\u0629 \u0627\u0644\u0646\u0627\u0639\u0645\u0629 \u0623\u0641\u0643 \u062A\u0634\u0627\u0628\u0643 \u0627\u0644\u0634\u0639\u0631 \u0628\u0631\u0642\u0629 \u062F\u0648\u0646 \u0623\u0644\u0645.", missingLetterWord: "die B_rste", sentence4Elements: ["Die", "weiche", "B\xFCrste", "macht das Haar glatt und gepflegt."] }
