      { id: "b05_121_10", german: "das Malheft", arabic: "\u0643\u0631\u0627\u0633 \u0627\u0644\u0631\u0633\u0645 \u0648\u0627\u0644\u062A\u0644\u0648\u064A\u0646 \u0644\u0644\u0623\u0637\u0641\u0627\u0644", article: "das", plural: "die Malhefte", emoji: "\u{1F4D2}", exampleSentenceGerman: "In das wei\xDFe Malheft zeichne ich Tiere und Blumen.", exampleSentenceArabic: "\u0641\u064A \u0643\u0631\u0627\u0633 \u0627\u0644\u0631\u0633\u0645 \u0627\u0644\u0623\u0628\u064A\u0636 \u0623\u0631\u0633\u0645 \u062D\u064A\u0648\u0627\u0646\u0627\u062A \u0648\u0632\u0647\u0648\u0631\u0627\u064B \u0628\u062F\u064A\u0639\u0629.", missingLetterWord: "M_lheft", sentence4Elements: ["Das", "dicke", "Malheft", "ist voller bunter Kunstwerke."] }
