      { id: "b05_133_08", german: "das Teeservice", arabic: "\u0637\u0642\u0645 \u0627\u0644\u0634\u0627\u064A \u0627\u0644\u0635\u063A\u064A\u0631 \u0627\u0644\u062A\u062E\u064A\u0644\u064A \u0644\u0644\u0636\u064A\u0648\u0641", article: "das", plural: "die Teeservices", emoji: "\u{1FAD6}", exampleSentenceGerman: "Kommen Sie herein zum Tee! Wir servieren mit winzigen Tassen.", exampleSentenceArabic: "\u062A\u0641\u0636\u0644\u0648\u0627 \u0644\u062A\u0646\u0627\u0648\u0644 \u0627\u0644\u0634\u0627\u064A! \u0646\u0642\u062F\u0645 \u0627\u0644\u0634\u0627\u064A \u0641\u064A \u0641\u0646\u0627\u062C\u064A\u0646 \u0635\u063A\u064A\u0631\u0629 \u062C\u0645\u064A\u0644\u0629.", missingLetterWord: "T_eservice", sentence4Elements: ["Das", "porzellanene", "Teeservice", "steht auf dem runden Tischchen bereit."] },
      { id: "b05_133_09", german: "der Kaufladen", arabic: "\u062F\u0643\u0627\u0646 \u0627\u0644\u0628\u0642\u0627\u0644\u0629 \u0627\u0644\u0635\u063A\u064A\u0631 \u0627\u0644\u062A\u062E\u064A\u0644\u064A \u0644\u0628\u064A\u0639 \u0627\u0644\u0628\u0636\u0627\u0626\u0639", article: "der", plural: "die Kaufl\xE4den", emoji: "\u{1F3EA}", exampleSentenceGerman: "Im Kaufladen verkaufen wir Holz\xE4pfel und Miniatur-Milcht\xFCten.", exampleSentenceArabic: "\u0641\u064A \u0627\u0644\u062F\u0643\u0627\u0646 \u0627\u0644\u062A\u062E\u064A\u0644\u064A \u0646\u0628\u064A\u0639 \u062A\u0641\u0627\u062D\u0627\u064B \u062E\u0634\u0628\u064A\u0627\u064B \u0648\u0639\u0628\u0648\u0627\u062A \u062D\u0644\u064A\u0628 \u0635\u063A\u064A\u0631\u0629.", missingLetterWord: "K_ufladen", sentence4Elements: ["Der", "Kaufladen", "hat", "eine Kasse mit Spielgeld."] },
      { id: "b05_133_10", german: "die Spielkasse", arabic: "\u0645\u0627\u0643\u064A\u0646\u0629 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u0646\u0642\u0648\u062F (\u0627\u0644\u0643\u0627\u0634\u064A\u0631) \u0645\u0639 \u0627\u0644\u0646\u0642\u0648\u062F \u0627\u0644\u0648\u0631\u0642\u064A\u0629", article: "die", plural: "die Spielkassen", emoji: "\u{1FA99}", exampleSentenceGerman: "Die Kasse piept und die Schublade springt mit M\xFCnzen auf.", exampleSentenceArabic: "\u062A\u0635\u062F\u0631 \u0645\u0627\u0643\u064A\u0646\u0629 \u0627\u0644\u0643\u0627\u0634\u064A\u0631 \u0635\u0641\u064A\u0631\u0627\u064B \u0648\u064A\u0646\u0641\u062A\u062D \u0627\u0644\u062F\u0631\u062C \u062D\u0627\u0645\u0644\u0627\u064B \u0646\u0642\u0648\u062F \u0627\u0644\u0644\u0639\u0628.", missingLetterWord: "Sp_elkasse", sentence4Elements: ["Mit", "der", "Kreditkarte", "bezahlen wir an der Spielkasse."] }
