      { id: "b05_134_07", german: "verlieren", arabic: "\u064A\u062E\u0633\u0631 \u0628\u0631\u0648\u062D \u0631\u064A\u0627\u0636\u064A\u0629 \u062F\u0648\u0646 \u063A\u0636\u0628", emoji: "\u{1F91D}", exampleSentenceGerman: "Auch Verlieren geh\xF6rt zum Spiel; wir gratulieren dem Sieger.", exampleSentenceArabic: "\u0627\u0644\u062E\u0633\u0627\u0631\u0629 \u062C\u0632\u0621 \u0645\u0646 \u0627\u0644\u0644\u0639\u0628 \u0623\u064A\u0636\u0627\u064B\u061B \u0646\u0628\u0627\u0631\u0643 \u0644\u0644\u0641\u0627\u0626\u0632 \u0628\u0631\u0648\u062D \u0631\u064A\u0627\u0636\u064A\u0629.", missingLetterWord: "v_rlieren", sentence4Elements: ["Gute", "Verlierer", "bleiben", "trotzdem fr\xF6hlich und fair."] },
      { id: "b05_134_08", german: "die Spielregeln", arabic: "\u0642\u0648\u0627\u0639\u062F \u0648\u0642\u0648\u0627\u0646\u064A\u0646 \u0627\u0644\u0644\u0639\u0628\u0629 \u0627\u0644\u0645\u0646\u0638\u0645\u0629", article: "die", plural: "die Spielregeln", emoji: "\u{1F4DC}", exampleSentenceGerman: "Vor dem Start lesen wir die einfachen Spielregeln durch.", exampleSentenceArabic: "\u0642\u0628\u0644 \u0627\u0644\u0628\u062F\u0621 \u0646\u0642\u0631\u0623 \u062A\u0639\u0644\u064A\u0645\u0627\u062A \u0648\u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0644\u0639\u0628\u0629 \u0627\u0644\u0628\u0633\u064A\u0637\u0629 \u0644\u0646\u062A\u0641\u0642.", missingLetterWord: "Sp_elregeln", sentence4Elements: ["Alle", "Spieler", "halten", "sich ehrlich an die Regeln."] },
      { id: "b05_134_09", german: "schummeln", arabic: "\u064A\u063A\u0634 \u0641\u064A \u0627\u0644\u0644\u0639\u0628 (\u0633\u0644\u0648\u0643 \u063A\u064A\u0631 \u0645\u0642\u0628\u0648\u0644)", emoji: "\u{1F648}", exampleSentenceGerman: "Bei uns wird nicht geschummelt, wir spielen ehrlich!", exampleSentenceArabic: "\u0641\u064A \u0623\u0644\u0639\u0627\u0628\u0646\u0627 \u0644\u0627 \u0623\u062D\u062F \u064A\u063A\u0634\u060C \u0646\u062D\u0646 \u0646\u0644\u0639\u0628 \u0628\u0623\u0645\u0627\u0646\u0629 \u0648\u0635\u062F\u0642 \u062A\u0627\u0645!", missingLetterWord: "sch_mmeln", sentence4Elements: ["Schummeln", "verdirbt", "allen", "den Spielspa\xDF."] },
      { id: "b05_134_10", german: "der Spielleiter", arabic: "\u062D\u0643\u0645 \u0627\u0644\u0644\u0639\u0628\u0629 \u0623\u0648 \u0627\u0644\u0645\u0646\u0638\u0645 \u0644\u0644\u062C\u0648\u0644\u0629", article: "der", plural: "die Spielleiter", emoji: "\u{1F9D1}\u200D\u2696\uFE0F", exampleSentenceGerman: "Der Spielleiter liest die Quizfragen vor und stoppt die Zeit.", exampleSentenceArabic: "\u064A\u0642\u0631\u0623 \u0645\u062F\u064A\u0631 \u0627\u0644\u0644\u0639\u0628\u0629 \u0623\u0633\u0626\u0644\u0629 \u0627\u0644\u0645\u0633\u0627\u0628\u0642\u0629 \u0648\u064A\u0636\u0628\u0637 \u0639\u062F\u0627\u062F \u0627\u0644\u0648\u0642\u062A.", missingLetterWord: "Sp_elleiter", sentence4Elements: ["Der", "Spielleiter", "achtet", "auf einen fairen Spielablauf."] }
