    descriptionTranslations: { ar: "\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u062D\u062F\u064A\u0642\u0629 \u0645\u062B\u0644 \u0627\u0644\u0623\u0631\u062C\u0648\u062D\u0629 \u0648\u0627\u0644\u0632\u062D\u0644\u064A\u0642\u0629 \u0648\u0635\u0646\u062F\u0648\u0642 \u0627\u0644\u0631\u0645\u0644.", de: "Schaukel, Rutsche, Wippe, Sandkasten.", en: "Swing, slide, seesaw, sandbox and bucket." },
