      { id: "b05_137_03", german: "das Kinderfahrrad", arabic: "\u062F\u0631\u0627\u062C\u0629 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0647\u0648\u0627\u0626\u064A\u0629 \u0627\u0644\u0645\u0632\u0648\u062F\u0629 \u0628\u0627\u0644\u0628\u062F\u0627\u0644\u0627\u062A", article: "das", plural: "die Kinderfahrr\xE4der", emoji: "\u{1F6B2}", exampleSentenceGerman: "Mein neues Fahrrad hat zwei Handbremsen und eine Klingel.", exampleSentenceArabic: "\u062F\u0631\u0627\u062C\u062A\u064A \u0627\u0644\u0647\u0648\u0627\u0626\u064A\u0629 \u0627\u0644\u062C\u062F\u064A\u062F\u0629 \u0645\u0632\u0648\u062F\u0629 \u0628\u0641\u0631\u0627\u0645\u0644 \u064A\u062F\u0648\u064A\u0629 \u0648\u062C\u0631\u0633 \u0645\u0646\u0628\u0647.", missingLetterWord: "K_nderfahrrad", sentence4Elements: ["Ich", "fahre", "schon", "sicher ohne St\xFCtzr\xE4der!"] },
      { id: "b05_137_04", german: "das Skateboard", arabic: "\u0644\u0648\u062D \u0627\u0644\u062A\u0632\u0644\u062C \u0630\u0648 \u0627\u0644\u0639\u062C\u0644\u0627\u062A \u0627\u0644\u0623\u0631\u0628\u0639 (\u0627\u0644\u0633\u0643\u064A\u062A \u0628\u0648\u0631\u062F)", article: "das", plural: "die Skateboards", emoji: "\u{1F6F9}", exampleSentenceGerman: "Im Skatepark \xFCbt er tolle Spr\xFCnge auf dem bunten Board.", exampleSentenceArabic: "\u0641\u064A \u062D\u062F\u064A\u0642\u0629 \u0627\u0644\u062A\u0632\u0644\u062C \u064A\u062A\u062F\u0631\u0628 \u0639\u0644\u0649 \u0642\u0641\u0632\u0627\u062A \u0645\u0630\u0647\u0644\u0629 \u0641\u0648\u0642 \u0644\u0648\u062D \u0627\u0644\u062A\u0632\u0644\u062C.", missingLetterWord: "Sk_teboard", sentence4Elements: ["Das", "Skateboard", "gleitet", "geschmeidig \xFCber die glatte Rampe."] },
      { id: "b05_137_05", german: "die Inlineskates", arabic: "\u062D\u0630\u0627\u0621 \u0627\u0644\u062A\u0632\u0644\u062C \u0628\u0627\u0644\u0639\u062C\u0644\u0627\u062A \u0627\u0644\u0637\u0648\u0644\u064A\u0629 (\u0627\u0644\u0628\u0627\u062A\u064A\u0646\u0627\u062C/\u0627\u0644\u0625\u0646\u0644\u0627\u064A\u0646)", article: "die", plural: "die Inlineskates", emoji: "\u{1F6FC}", exampleSentenceGerman: "Auf Inlineskates rolle ich sanft den asphaltierten Weg entlang.", exampleSentenceArabic: "\u0628\u062D\u0630\u0627\u0621 \u0627\u0644\u062A\u0632\u0644\u062C \u0630\u064A \u0627\u0644\u0639\u062C\u0644\u0627\u062A \u0623\u0646\u0632\u0644\u0642 \u0628\u0646\u0639\u0648\u0645\u0629 \u0639\u0644\u0649 \u0637\u0631\u064A\u0642 \u0627\u0644\u0625\u0633\u0641\u0644\u062A.", missingLetterWord: "_nlineskates", sentence4Elements: ["Inlineskaten", "macht", "an", "sonnigen Nachmittagen gro\xDFen Spa\xDF."] },
      { id: "b05_137_06", german: "der Schutzhelm", arabic: "\u062E\u0648\u0630\u0629 \u062D\u0645\u0627\u064A\u0629 \u0627\u0644\u0631\u0623\u0633 \u0627\u0644\u0625\u0644\u0632\u0627\u0645\u064A\u0629 \u0644\u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u0623\u0637\u0641\u0627\u0644", article: "der", plural: "die Schutzhelme", emoji: "\u26D1\uFE0F", exampleSentenceGerman: "Klick! Ohne Helm steige ich nie aufs Skateboard oder Rad.", exampleSentenceArabic: "\u0643\u0644\u064A\u0643! \u062F\u0648\u0646 \u062E\u0648\u0630\u0629 \u0648\u0627\u0642\u064A\u0629 \u0644\u0627 \u0623\u0635\u0639\u062F \u0623\u0628\u062F\u0627\u064B \u0639\u0644\u0649 \u0627\u0644\u062F\u0631\u0627\u062C\u0629 \u0623\u0648 \u0627\u0644\u0644\u0648\u062D.", missingLetterWord: "Sch_tzhelm", sentence4Elements: ["Ein", "gut", "sitzender", "Helm bewahrt den Kopf vor Beulen."] },
      { id: "b05_137_07", german: "die Knieschoner", arabic: "\u0648\u0627\u0642\u064A\u0627\u062A \u0627\u0644\u0631\u0643\u0628\u062A\u064A\u0646 \u0627\u0644\u0645\u0628\u0637\u0646\u0629 \u0644\u0644\u062D\u0645\u0627\u064A\u0629 \u0645\u0646 \u0627\u0644\u062E\u062F\u0648\u0634", article: "die", plural: "die Knieschoner", emoji: "\u{1F6E1}\uFE0F", exampleSentenceGerman: "Knieschoner d\xE4mpfen sanft ab, falls man doch einmal stolpert.", exampleSentenceArabic: "\u0648\u0627\u0642\u064A\u0627\u062A \u0627\u0644\u0631\u0643\u0628\u0629 \u062A\u0645\u062A\u0635 \u0627\u0644\u0635\u062F\u0645\u0629 \u0628\u0631\u0641\u0642 \u0625\u0630\u0627 \u062A\u0639\u062B\u0631 \u0627\u0644\u0637\u0641\u0644 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062A\u0632\u0644\u062C.", missingLetterWord: "Kn_eschoner", sentence4Elements: ["Schoner", "an", "Knien", "und Ellbogen sch\xFCtzen vor Schrammen."] },
      { id: "b05_137_08", german: "die Fahrradklingel", arabic: "\u062C\u0631\u0633 \u0627\u0644\u062F\u0631\u0627\u062C\u0629 \u0627\u0644\u0631\u0646\u0627\u0646 \u0644\u062A\u0646\u0628\u064A\u0647 \u0627\u0644\u0645\u0634\u0627\u0629", article: "die", plural: "die Fahrradklingeln", emoji: "\u{1F514}", exampleSentenceGerman: "Klingeling! Mit der Klingel warne ich die Fu\xDFg\xE4nger rechtzeitig.", exampleSentenceArabic: "\u062A\u0631\u0646 \u062A\u0631\u0646! \u0628\u0627\u0644\u062C\u0631\u0633 \u0623\u0646\u0628\u0647 \u0627\u0644\u0645\u0634\u0627\u0629 \u0639\u0644\u0649 \u0627\u0644\u0631\u0635\u064A\u0641 \u0641\u064A \u0627\u0644\u0648\u0642\u062A \u0627\u0644\u0645\u0646\u0627\u0633\u0628.", missingLetterWord: "Kl_ngel", sentence4Elements: ["Die", "helle", "Klingel", "ert\xF6nt laut und freundlich."] },
      { id: "b05_137_09", german: "die Fahrradpumpe", arabic: "\u0645\u0646\u0641\u0627\u062E \u0625\u0637\u0627\u0631\u0627\u062A \u0627\u0644\u062F\u0631\u0627\u062C\u0629 \u0627\u0644\u064A\u062F\u0648\u064A", article: "die", plural: "die Fahrradpumpen", emoji: "\u{1F4A8}", exampleSentenceGerman: "Mit der Luftpumpe pumpen wir die weichen Reifen wieder prall auf.", exampleSentenceArabic: "\u0628\u0627\u0644\u0645\u0646\u0641\u0627\u062E \u0627\u0644\u064A\u062F\u0648\u064A \u0646\u0645\u0644\u0623 \u0625\u0637\u0627\u0631\u0627\u062A \u0627\u0644\u062F\u0631\u0627\u062C\u0629 \u0627\u0644\u0647\u0648\u0627\u0626\u064A\u0629 \u0628\u0627\u0644\u0647\u0648\u0627\u0621 \u0645\u062C\u062F\u062F\u0627\u064B.", missingLetterWord: "F_hrradpumpe", sentence4Elements: ["Die", "Pumpe", "dr\xFCckt", "schnell frische Luft in den Schlauch."] },
      { id: "b05_137_10", german: "das Fahrradschloss", arabic: "\u0642\u0641\u0644 \u0627\u0644\u062F\u0631\u0627\u062C\u0629 \u0627\u0644\u0641\u0648\u0644\u0627\u0630\u064A \u0644\u062D\u0645\u0627\u064A\u062A\u0647\u0627 \u0645\u0646 \u0627\u0644\u0633\u0631\u0642\u0629", article: "das", plural: "die Fahrradschl\xF6sser", emoji: "\u{1F512}", exampleSentenceGerman: "Vor der Schule schlie\xDFe ich mein Rad mit dem Schloss fest an.", exampleSentenceArabic: "\u0623\u0645\u0627\u0645 \u0627\u0644\u0645\u062F\u0631\u0633\u0629 \u0623\u0642\u0641\u0644 \u062F\u0631\u0627\u062C\u062A\u064A \u0628\u0627\u0644\u0642\u0641\u0644 \u0627\u0644\u0645\u062A\u064A\u0646 \u0628\u0627\u0644\u0639\u0645\u0648\u062F \u0628\u0625\u062D\u0643\u0627\u0645.", missingLetterWord: "Schl_ss", sentence4Elements: ["Mit", "einem", "Zahlencode", "\xF6ffnet sich das stabile Kettenschloss."] }
