      { id: "b05_139_04", german: "der Wasserbecher", arabic: "\u0643\u0648\u0628 \u063A\u0633\u064A\u0644 \u0627\u0644\u0641\u0631\u0634\u0627\u0629 \u0628\u0627\u0644\u0645\u0627\u0621 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062A\u0644\u0648\u064A\u0646", article: "der", plural: "die Wasserbecher", emoji: "\u{1F964}", exampleSentenceGerman: "Im Wasserbecher wasche ich die Farbe aus den Pinselborsten.", exampleSentenceArabic: "\u0641\u064A \u0643\u0648\u0628 \u0627\u0644\u0645\u0627\u0621 \u0623\u063A\u0633\u0644 \u0627\u0644\u0644\u0648\u0646 \u0639\u0646 \u0634\u0639\u064A\u0631\u0627\u062A \u0627\u0644\u0641\u0631\u0634\u0627\u0629 \u0642\u0628\u0644 \u0623\u062E\u0630 \u0644\u0648\u0646 \u0622\u062E\u0631.", missingLetterWord: "W_sserbecher", sentence4Elements: ["Das", "Wasser", "im", "Becher f\xE4rbt sich allm\xE4hlich bunt."] },
      { id: "b05_139_05", german: "das Tonpapier", arabic: "\u0648\u0631\u0642 \u0627\u0644\u0643\u0627\u0646\u0633\u0648\u0646 \u0627\u0644\u0645\u0644\u0648\u0646 \u0627\u0644\u0633\u0645\u064A\u0643 \u0644\u0644\u0623\u0634\u063A\u0627\u0644 \u0627\u0644\u064A\u062F\u0648\u064A\u0629", article: "das", plural: "die Tonpapiere", emoji: "\u{1F4C4}", exampleSentenceGerman: "Aus stabilem rotem Tonpapier schneiden wir Herzen aus.", exampleSentenceArabic: "\u0645\u0646 \u0648\u0631\u0642 \u0627\u0644\u0643\u0627\u0646\u0633\u0648\u0646 \u0627\u0644\u0623\u062D\u0645\u0631 \u0627\u0644\u0645\u0642\u0648\u0649 \u0646\u0642\u0635 \u0642\u0644\u0648\u0628\u0627\u064B \u062C\u0645\u064A\u0644\u0629 \u0644\u0644\u0628\u0637\u0627\u0642\u0629.", missingLetterWord: "T_npapier", sentence4Elements: ["Buntes", "Tonpapier", "gibt", "unserer Bastelarbeit Festigkeit."] },
      { id: "b05_139_06", german: "der Bastelkleber", arabic: "\u0635\u0645\u063A \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u064A\u062F\u0648\u064A\u0629 \u0627\u0644\u0633\u0627\u0626\u0644 \u0630\u0648 \u0627\u0644\u0631\u0623\u0633 \u0627\u0644\u062F\u0642\u064A\u0642", article: "der", plural: "die Bastelkleber", emoji: "\u{1F9F4}", exampleSentenceGerman: "Mit fl\xFCssigem Bastelkleber halten Pappe und Holz bombenfest.", exampleSentenceArabic: "\u0628\u0627\u0644\u0635\u0645\u063A \u0627\u0644\u0633\u0627\u0626\u0644 \u0644\u0644\u0623\u0634\u063A\u0627\u0644 \u062A\u062B\u0628\u062A \u0627\u0644\u0648\u0631\u0642 \u0627\u0644\u0645\u0642\u0648\u0649 \u0648\u0627\u0644\u062E\u0634\u0628 \u0628\u0642\u0648\u0629 \u062A\u0627\u0645\u0629.", missingLetterWord: "B_stelkleber", sentence4Elements: ["Ein", "Tropfen", "Kleber", "gen\xFCgt f\xFCr die kleine Ecke."] },
      { id: "b05_139_07", german: "der Glitzer", arabic: "\u0628\u0648\u062F\u0631\u0629 \u0627\u0644\u0628\u0631\u064A\u0642 \u0627\u0644\u0644\u0627\u0645\u0639\u0629 (\u0627\u0644\u062C\u0644\u064A\u062A\u0631 \u0627\u0644\u0628\u0631\u0627\u0642)", article: "der", plural: "die Glitzer", emoji: "\u2728", exampleSentenceGerman: "Goldener Glitzer l\xE4sst unsere Geburtstagskarte magisch funkeln.", exampleSentenceArabic: "\u0627\u0644\u0628\u0631\u064A\u0642 \u0627\u0644\u0630\u0647\u0628\u064A \u064A\u062C\u0639\u0644 \u0628\u0637\u0627\u0642\u0629 \u0639\u064A\u062F \u0627\u0644\u0645\u064A\u0644\u0627\u062F \u062A\u062A\u0644\u0623\u0644\u0623 \u0628\u0633\u062D\u0631 \u062C\u0630\u0627\u0628.", missingLetterWord: "der Gl_tzer", sentence4Elements: ["Wir", "streuen", "etwas", "Glitzer \xFCber den noch feuchten Leim."] },
      { id: "b05_139_08", german: "die Holzperlen", arabic: "\u062E\u0631\u0632 \u0627\u0644\u062E\u0634\u0628 \u0627\u0644\u0645\u0644\u0648\u0646 \u0644\u0644\u062A\u0634\u0643\u064A\u0644 \u0648\u0635\u0646\u0639 \u0627\u0644\u0623\u0633\u0627\u0648\u0631", article: "die", plural: "die Holzperlen", emoji: "\u{1F4FF}", exampleSentenceGerman: "Ich f\xE4dle bunte Holzperlen auf eine elastische Schnur.", exampleSentenceArabic: "\u0623\u0646\u0638\u0645 \u062D\u0628\u0627\u062A \u062E\u0631\u0632 \u062E\u0634\u0628\u064A\u0629 \u0645\u0644\u0648\u0646\u0629 \u0641\u064A \u062E\u064A\u0637 \u0645\u0631\u0646 \u0644\u0623\u0635\u0646\u0639 \u0639\u0642\u062F\u0627\u064B.", missingLetterWord: "H_lzperlen", sentence4Elements: ["Aus", "den", "Perlen", "entsteht ein h\xFCbsches Freundschaftsarmband."] },
      { id: "b05_139_09", german: "die Malunterlage", arabic: "\u0645\u0641\u0631\u0634 \u062D\u0645\u0627\u064A\u0629 \u0627\u0644\u0637\u0627\u0648\u0644\u0629 \u0627\u0644\u0628\u0644\u0627\u0633\u062A\u064A\u0643\u064A \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u0631\u0633\u0645", article: "die", plural: "die Malunterlagen", emoji: "\u{1F5DE}\uFE0F", exampleSentenceGerman: "Eine abwischbare Unterlage sch\xFCtzt den Holztisch vor Flecken.", exampleSentenceArabic: "\u0645\u0641\u0631\u0634 \u0628\u0644\u0627\u0633\u062A\u064A\u0643\u064A \u0642\u0627\u0628\u0644 \u0644\u0644\u0645\u0633\u062D \u064A\u062D\u0645\u064A \u0627\u0644\u0637\u0627\u0648\u0644\u0629 \u0645\u0646 \u0628\u0642\u0639 \u0627\u0644\u0623\u0644\u0648\u0627\u0646.", missingLetterWord: "M_lunterlage", sentence4Elements: ["Breite", "zuerst", "die", "Malunterlage auf dem Schreibtisch aus!"] },
      { id: "b05_139_10", german: "der Malkittel", arabic: "\u0645\u0631\u064A\u0644\u0629 \u0623\u0648 \u0631\u062F\u0627\u0621 \u0627\u0644\u0631\u0633\u0645 \u0627\u0644\u0648\u0627\u0642\u064A \u0644\u0645\u0644\u0627\u0628\u0633 \u0627\u0644\u0623\u0637\u0641\u0627\u0644", article: "der", plural: "die Malkittel", emoji: "\u{1F97C}", exampleSentenceGerman: "Im bunten Malkittel bleiben meine Pullover sauber.", exampleSentenceArabic: "\u0641\u064A \u0631\u062F\u0627\u0621 \u0627\u0644\u0631\u0633\u0645 \u0627\u0644\u0645\u0644\u0648\u0646 \u062A\u0628\u0642\u0649 \u0645\u0644\u0627\u0628\u0633\u064A \u0646\u0638\u064A\u0641\u0629 \u0648\u062E\u0627\u0644\u064A\u0629 \u0645\u0646 \u0627\u0644\u0623\u0644\u0648\u0627\u0646.", missingLetterWord: "M_lkittel", sentence4Elements: ["Zieh", "deinen", "Malkittel", "an, bevor du mit Farben spritzt!"] }
