      { id: "b06_157_08", german: "der Sonnenschirm", arabic: "\u0645\u0638\u0644\u0629 \u0627\u0644\u062D\u062F\u064A\u0642\u0629 \u0627\u0644\u0643\u0628\u064A\u0631\u0629 \u0644\u0644\u0648\u0642\u0627\u064A\u0629 \u0645\u0646 \u062D\u0631\u0627\u0631\u0629 \u0627\u0644\u0634\u0645\u0633", article: "der", plural: "die Sonnenschirme", emoji: "\u26F1\uFE0F", exampleSentenceGerman: "Unter dem gro\xDFen Schirm sitzen wir mittags angenehm im Schatten.", exampleSentenceArabic: "\u062A\u062D\u062A \u0627\u0644\u0645\u0638\u0644\u0629 \u0627\u0644\u0643\u0628\u064A\u0631\u0629 \u0646\u062C\u0644\u0633 \u0638\u0647\u0631\u0627\u064B \u0628\u0627\u0633\u062A\u0631\u062E\u0627\u0621 \u0641\u064A \u0627\u0644\u0638\u0644 \u0627\u0644\u0645\u0646\u0639\u0634.", missingLetterWord: "S_nnenschirm", sentence4Elements: ["Der", "Sonnenschirm", "sch\xFCtzt", "vor hei\xDFer Sommersonne."] },
      { id: "b06_157_09", german: "der Blumentopf", arabic: "\u0623\u0635\u064A\u0635 \u0627\u0644\u0632\u0647\u0648\u0631 \u0627\u0644\u062E\u0632\u0641\u064A \u0627\u0644\u0645\u0644\u0648\u0646 (\u0627\u0644\u0645\u0632\u0647\u0631\u064A\u0629 \u0644\u0644\u0632\u0631\u0639)", article: "der", plural: "die Blument\xF6pfe", emoji: "\u{1FAB4}", exampleSentenceGerman: "Auf dem Balkon leuchten rote Geranien im Blumentopf.", exampleSentenceArabic: "\u0641\u064A \u0627\u0644\u0634\u0631\u0641\u0629 \u062A\u062A\u0644\u0623\u0644\u0623 \u0632\u0647\u0648\u0631 \u0627\u0644\u062C\u064A\u0631\u0627\u0646\u064A\u0648\u0645 \u0627\u0644\u062D\u0645\u0631\u0627\u0621 \u0641\u064A \u0627\u0644\u0623\u0635\u064A\u0635 \u0627\u0644\u0641\u062E\u0627\u0631\u064A.", missingLetterWord: "Bl_mentopf", sentence4Elements: ["In", "jedem", "Tontopf", "bl\xFCht eine andere fr\xF6hliche Sommerblume."] },
      { id: "b06_157_10", german: "der Gartengrill", arabic: "\u0634\u0648\u0627\u064A\u0629 \u0627\u0644\u062D\u062F\u064A\u0642\u0629 \u0644\u062D\u0641\u0644\u0627\u062A \u0627\u0644\u0634\u0648\u0627\u0621 \u0627\u0644\u0644\u0630\u064A\u0630\u0629 (\u0627\u0644\u0628\u0627\u0631\u0628\u0643\u064A\u0648)", article: "der", plural: "die Gartengrills", emoji: "\u{1F969}", exampleSentenceGerman: "Auf dem Holzkohlegrill braten W\xFCrstchen und Gem\xFCsespie\xDFe.", exampleSentenceArabic: "\u0639\u0644\u0649 \u0634\u0648\u0627\u064A\u0629 \u0627\u0644\u0641\u062D\u0645 \u062A\u0646\u0636\u062C \u0627\u0644\u0646\u0642\u0627\u0646\u0642 \u0648\u0623\u0633\u064A\u0627\u062E \u0627\u0644\u062E\u0636\u0627\u0631 \u0627\u0644\u0645\u0634\u0648\u064A\u0629 \u0628\u0631\u0627\u0626\u062D\u0629 \u0634\u0647\u064A\u0629.", missingLetterWord: "G_rtengrill", sentence4Elements: ["Der", "Duft", "vom", "Grill lockt alle hungrig an den Gartentisch."] }
