    topicTranslations: { ar: "\u0627\u0644\u0628\u064A\u062A \u0648\u0627\u0644\u0623\u062B\u0627\u062B", de: "Haushalt & Pflichten", en: "Household Chores" },
    grade: "\u062C\u0631\u064A\u062F 2",
