      { id: "b06_164_09", german: "das Fu\xDFballstadion", arabic: "\u0627\u0633\u062A\u0627\u062F \u0648\u0645\u0644\u0639\u0628 \u0643\u0631\u0629 \u0627\u0644\u0642\u062F\u0645 \u0627\u0644\u0643\u0628\u064A\u0631 \u0644\u0644\u0645\u0628\u0627\u0631\u064A\u0627\u062A", article: "das", plural: "die Fu\xDFballstadien", emoji: "\u{1F3DF}\uFE0F", exampleSentenceGerman: "Tausende Fans jubeln im Stadion und schwenken Vereinsfahnen.", exampleSentenceArabic: "\u0622\u0644\u0627\u0641 \u0627\u0644\u0645\u0634\u062C\u0639\u064A\u0646 \u064A\u0647\u062A\u0641\u0648\u0646 \u0641\u064A \u0627\u0644\u0627\u0633\u062A\u0627\u062F \u0645\u0644\u0648\u062D\u064A\u0646 \u0628\u0631\u0627\u064A\u0627\u062A \u0648\u0623\u0639\u0644\u0627\u0645 \u0627\u0644\u0641\u0631\u064A\u0642.", missingLetterWord: "St_dion", sentence4Elements: ["Die", "gr\xFCne", "Spielfl\xE4che", "wird von Flutlichtmasten taghell erleuchtet."] },
      { id: "b06_164_10", german: "der Vergn\xFCgungspark", arabic: "\u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0645\u0644\u0627\u0647\u064A \u0627\u0644\u062A\u0631\u0641\u064A\u0647\u064A\u0629 \u0648\u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u062F\u0648\u0627\u0631\u0629", article: "der", plural: "die Vergn\xFCgungsparks", emoji: "\u{1F3A1}", exampleSentenceGerman: "Im Freizeitpark fahren wir mit der rasanten Achterbahn.", exampleSentenceArabic: "\u0641\u064A \u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0645\u0644\u0627\u0647\u064A \u0646\u0631\u0643\u0628 \u0642\u0637\u0627\u0631 \u0627\u0644\u0645\u0648\u062A \u0627\u0644\u0633\u0631\u064A\u0639 \u0648\u0639\u062C\u0644\u0629 \u0627\u0644\u0647\u0648\u0627\u0621 \u0627\u0644\u062F\u0648\u0627\u0631\u0629.", missingLetterWord: "V_rgn\xFCgungspark", sentence4Elements: ["Das", "hohe", "Riesenrad", "dreht sich langsam hoch \xFCber die Baumwipfel."] }
