      { id: "b06_168_09", german: "die Endstation", arabic: "\u0627\u0644\u0645\u062D\u0637\u0629 \u0627\u0644\u0646\u0647\u0627\u0626\u064A\u0629 / \u0622\u062E\u0631 \u0645\u062D\u0637\u0629 \u0641\u064A \u062E\u0637 \u0627\u0644\u0631\u062D\u0644\u0629", article: "die", plural: "die Endstationen", emoji: "\u{1F6D1}", exampleSentenceGerman: "Endstation! Bitte alle Fahrg\xE4ste aussteigen, der Zug wendet hier.", exampleSentenceArabic: "\u0627\u0644\u0645\u062D\u0637\u0629 \u0627\u0644\u0623\u062E\u064A\u0631\u0629! \u064A\u0631\u062C\u0649 \u0645\u0646 \u062C\u0645\u064A\u0639 \u0627\u0644\u0631\u0643\u0627\u0628 \u0627\u0644\u0646\u0632\u0648\u0644\u060C \u0627\u0644\u0642\u0637\u0627\u0631 \u0633\u064A\u0646\u0639\u0637\u0641 \u0647\u0646\u0627.", missingLetterWord: "_ndstation", sentence4Elements: ["An", "der", "Endstation", "f\xE4hrt die Bahn in die Abstellanlage."] },
      { id: "b06_168_10", german: "die Seilbahn", arabic: "\u0627\u0644\u062A\u0644\u0641\u0631\u064A\u0643 \u0627\u0644\u062C\u0628\u0644\u064A \u0627\u0644\u0645\u0639\u0644\u0642 \u0641\u064A \u0627\u0644\u0647\u0648\u0627\u0621 \u0644\u0644\u0635\u0639\u0648\u062F \u0644\u0644\u0642\u0645\u0629", article: "die", plural: "die Seilbahnen", emoji: "\u{1F6A1}", exampleSentenceGerman: "Die Panorama-Gondel der Seilbahn schwebt hinauf zum Berggipfel.", exampleSentenceArabic: "\u0639\u0631\u0628\u0629 \u0627\u0644\u062A\u0644\u0641\u0631\u064A\u0643 \u0627\u0644\u0645\u0639\u0644\u0642\u0629 \u062A\u0637\u0641\u0648 \u0641\u064A \u0627\u0644\u0647\u0648\u0627\u0621 \u0635\u0627\u0639\u062F\u0629 \u0646\u062D\u0648 \u0642\u0645\u0629 \u0627\u0644\u062C\u0628\u0644 \u0627\u0644\u0634\u0627\u0647\u0642\u0629.", missingLetterWord: "S_ilbahn", sentence4Elements: ["Aus", "der", "schwebenden", "Kabine hat man eine atemberaubende Aussicht."] }
