    topic: "\u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0648\u0627\u0644\u0645\u0648\u0627\u0642\u0641 \u0627\u0644\u064A\u0648\u0645\u064A\u0629",
    topicTranslations: { ar: "\u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0648\u0627\u0644\u0645\u0648\u0627\u0642\u0641 \u0627\u0644\u064A\u0648\u0645\u064A\u0629", de: "Verkehr & Sicherheit", en: "Traffic Safety" },
