      { id: "b06_177_09", german: "der Bergsee", arabic: "\u0627\u0644\u0628\u062D\u064A\u0631\u0629 \u0627\u0644\u062C\u0628\u0644\u064A\u0629 \u0627\u0644\u0635\u0627\u0641\u064A\u0629 \u0643\u0627\u0644\u0628\u0644\u0648\u0631 \u0628\u064A\u0646 \u0627\u0644\u0642\u0645\u0645", article: "der", plural: "die Bergseen", emoji: "\u{1F3DE}\uFE0F", exampleSentenceGerman: "Das glasklare Wasser des Bergsees spiegelt die Felsen wider.", exampleSentenceArabic: "\u0645\u064A\u0627\u0647 \u0627\u0644\u0628\u062D\u064A\u0631\u0629 \u0627\u0644\u062C\u0628\u0644\u064A\u0629 \u0627\u0644\u0646\u0642\u064A\u0629 \u062A\u0639\u0643\u0633 \u0635\u0648\u0631\u0629 \u0627\u0644\u062C\u0628\u0627\u0644 \u0627\u0644\u0645\u062D\u064A\u0637\u0629 \u0628\u062C\u0645\u0627\u0644.", missingLetterWord: "B_rgsee", sentence4Elements: ["Im", "kalten", "See", "tauchen wir kurz die m\xFCden F\xFC\xDFe ab."] },
      { id: "b06_177_10", german: "die Taschenlampe", arabic: "\u0627\u0644\u0645\u0635\u0628\u0627\u062D \u0627\u0644\u064A\u062F\u0648\u064A \u0627\u0644\u0643\u0634\u0627\u0641 \u0644\u0625\u0636\u0627\u0621\u0629 \u0627\u0644\u0644\u064A\u0644 \u0628\u0627\u0644\u062E\u064A\u0645\u0629", article: "die", plural: "die Taschenlampen", emoji: "\u{1F526}", exampleSentenceGerman: "Mit der Taschenlampe leuchten wir den Pfad zum Zelt aus.", exampleSentenceArabic: "\u0628\u0627\u0644\u0645\u0635\u0628\u0627\u062D \u0627\u0644\u064A\u062F\u0648\u064A \u0646\u0636\u064A\u0621 \u0627\u0644\u0637\u0631\u064A\u0642 \u0627\u0644\u0645\u0624\u062F\u064A \u0625\u0644\u0649 \u0627\u0644\u062E\u064A\u0645\u0629 \u0641\u064A \u0627\u0644\u0638\u0644\u0627\u0645.", missingLetterWord: "T_schenlampe", sentence4Elements: ["Ein", "heller", "Lichtkegel", "durchschneidet die dunkle Waldesnacht."] }
