      { id: "b06_178_09", german: "das Hallensportzentrum", arabic: "\u0627\u0644\u0645\u062C\u0645\u0639 \u0627\u0644\u0631\u064A\u0627\u0636\u064A \u0648\u0627\u0644\u0635\u0627\u0644\u0627\u062A \u0627\u0644\u0623\u0648\u0644\u0645\u0628\u064A\u0629 \u0627\u0644\u0645\u062A\u0639\u062F\u062F\u0629", article: "das", plural: "die Sportzentren", emoji: "\u{1F94B}", exampleSentenceGerman: "Im Sportzentrum trainieren Turn-, Judo- und Basketballgruppen.", exampleSentenceArabic: "\u0641\u064A \u0627\u0644\u0645\u062C\u0645\u0639 \u0627\u0644\u0631\u064A\u0627\u0636\u064A \u0627\u0644\u0643\u0628\u064A\u0631 \u062A\u062A\u062F\u0631\u0628 \u0641\u0631\u0642 \u0627\u0644\u062C\u0645\u0628\u0627\u0632 \u0648\u0627\u0644\u062C\u0648\u062F\u0648 \u0648\u0643\u0631\u0629 \u0627\u0644\u0633\u0644\u0629.", missingLetterWord: "Sp_rtzentrum", sentence4Elements: ["Moderne", "Hallen", "bieten", "optimale Bedingungen f\xFCr jeden Sport."] },
      { id: "b06_178_10", german: "der Seniorentreff", arabic: "\u0646\u0627\u062F\u064A \u0648\u0627\u0633\u062A\u0631\u0627\u062D\u0629 \u0643\u0628\u0627\u0631 \u0627\u0644\u0633\u0646 \u0648\u0627\u0644\u0623\u062C\u062F\u0627\u062F \u0644\u0644\u0623\u0646\u0634\u0637\u0629", article: "der", plural: "die Seniorentreffs", emoji: "\u{1F475}", exampleSentenceGerman: "Oma besucht dienstags den Seniorentreff zum Kaffeeklatsch und Bingo.", exampleSentenceArabic: "\u062A\u0632\u0648\u0631 \u062C\u062F\u062A\u064A \u064A\u0648\u0645 \u0627\u0644\u062B\u0644\u0627\u062B\u0627\u0621 \u0646\u0627\u062F\u064A \u0643\u0628\u0627\u0631 \u0627\u0644\u0633\u0646 \u0644\u0627\u062D\u062A\u0633\u0627\u0621 \u0627\u0644\u0642\u0647\u0648\u0629 \u0648\u0644\u0639\u0628 \u0627\u0644\u0628\u064A\u0646\u063A\u0648.", missingLetterWord: "S_niorentreff", sentence4Elements: ["Gemeinsames", "Lachen", "h\xE4lt", "K\xF6rper und Geist bis ins hohe Alter fit."] }
