      { id: "b07_182_09", german: "der Fliesenleger", arabic: "\u0641\u0646\u064A \u062A\u0631\u0643\u064A\u0628 \u0627\u0644\u0633\u064A\u0631\u0627\u0645\u064A\u0643 \u0648\u0627\u0644\u0628\u0644\u0627\u0637 \u0628\u0627\u0644\u0623\u0631\u0636\u064A\u0627\u062A \u0648\u0627\u0644\u062C\u062F\u0631\u0627\u0646", article: "der", plural: "die Fliesenleger", emoji: "\u{1F9F1}", exampleSentenceGerman: "Schnurgerade verlegt der Fliesenleger gl\xE4nzende Kacheln im Bad.", exampleSentenceArabic: "\u0628\u0627\u0633\u062A\u0642\u0627\u0645\u0629 \u0645\u062A\u0642\u0646\u0629 \u064A\u0631\u0643\u0628 \u0641\u0646\u064A \u0627\u0644\u0633\u064A\u0631\u0627\u0645\u064A\u0643 \u0627\u0644\u0628\u0644\u0627\u0637 \u0627\u0644\u0644\u0627\u0645\u0639 \u0641\u064A \u0627\u0644\u062D\u0645\u0627\u0645.", missingLetterWord: "Fl_esenleger", sentence4Elements: ["Mit", "feinem", "M\xF6rtel", "verfugt er alle Zwischenr\xE4ume sauber."] },
      { id: "b07_182_10", german: "der Schlosser", arabic: "\u0641\u0646\u064A \u062A\u0634\u0643\u064A\u0644 \u0648\u0644\u062D\u0627\u0645 \u0627\u0644\u0645\u0639\u0627\u062F\u0646 \u0648\u0627\u0644\u0623\u0642\u0641\u0627\u0644 (\u0627\u0644\u062D\u062F\u0627\u062F)", article: "der", plural: "die Schlosser", emoji: "\u2699\uFE0F", exampleSentenceGerman: "Der Schlosser schmiedet und schwei\xDFt stabile eiserne Gel\xE4nder.", exampleSentenceArabic: "\u064A\u0634\u0643\u0644 \u0641\u0646\u064A \u0627\u0644\u0645\u0639\u0627\u062F\u0646 \u0648\u064A\u0644\u062D\u0645 \u062F\u0631\u0627\u0628\u0632\u064A\u0646 \u0627\u0644\u0633\u0644\u0627\u0644\u0645 \u0627\u0644\u062D\u062F\u064A\u062F\u064A\u0629 \u0627\u0644\u0645\u062A\u064A\u0646\u0629.", missingLetterWord: "Schl_sser", sentence4Elements: ["Aus", "hartem", "Stahl", "fertigt er ma\xDFgenaue Tore und Schl\xF6sser."] }
