      { id: "b07_193_10", german: "der Winteranfang", arabic: "\u0628\u062F\u0627\u064A\u0629 \u0641\u0635\u0644 \u0627\u0644\u0634\u062A\u0627\u0621 \u0648\u0623\u0642\u0635\u0631 \u0646\u0647\u0627\u0631 \u0641\u064A \u0627\u0644\u0639\u0627\u0645", article: "der", plural: "die Winteranf\xE4nge", emoji: "\u{1F976}", exampleSentenceGerman: "Am k\xFCrzesten Tag des Jahres beginnt offiziell der Winter.", exampleSentenceArabic: "\u0641\u064A \u0623\u0642\u0635\u0631 \u0646\u0647\u0627\u0631 \u0641\u064A \u0627\u0644\u0639\u0627\u0645 \u064A\u0628\u062F\u0623 \u0641\u0635\u0644 \u0627\u0644\u0634\u062A\u0627\u0621 \u0631\u0633\u0645\u064A\u0627\u064B \u0628\u0644\u064A\u0627\u0644\u064A\u0647 \u0627\u0644\u0637\u0648\u064A\u0644\u0629.", missingLetterWord: "W_nteranfang", sentence4Elements: ["Zur", "Wintersonnenwende", "werden", "die Tage allm\xE4hlich wieder l\xE4nger."] }
