    topicTranslations: { ar: "\u0627\u0644\u0648\u0642\u062A \u0648\u0627\u0644\u0631\u0648\u062A\u064A\u0646 \u0627\u0644\u064A\u0648\u0645\u064A", de: "Nachmittagsroutine", en: "Afternoon Routine" },
