    descriptionTranslations: { ar: "\u0623\u0641\u0639\u0627\u0644 \u0627\u0644\u062D\u0631\u0643\u0629 \u0643\u0627\u0644\u0645\u0634\u064A \u0648\u0627\u0644\u0631\u0643\u0636 \u0648\u0627\u0644\u0642\u0641\u0632 \u0648\u0627\u0644\u062A\u0633\u0644\u0642.", de: "Gehen, rennen, springen, h\xFCpfen, klettern.", en: "Walk, run, jump, hop, climb, dance." },
