    topicTranslations: { ar: "\u0627\u0644\u0623\u0641\u0639\u0627\u0644 \u0648\u0627\u0644\u0623\u0646\u0634\u0637\u0629", de: "Essen & Trinken", en: "Eating & Drinking" },
