    descriptionTranslations: { ar: "\u0645\u0647\u0627\u0631\u0627\u062A \u0643\u0631\u0629 \u0627\u0644\u0642\u062F\u0645 \u0643\u0627\u0644\u0645\u0631\u0627\u0648\u063A\u0629 \u0648\u0627\u0644\u062A\u0633\u062F\u064A\u062F \u0648\u0627\u0644\u062A\u0645\u0631\u064A\u0631.", de: "Dribbeln, passen, schie\xDFen, k\xF6pfen, jubeln.", en: "Dribble, pass, shoot, header, cheer, score." },
