    topic: "\u0627\u0644\u0631\u064A\u0627\u0636\u0629 \u0648\u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0628\u062F\u0646\u064A",
    topicTranslations: { ar: "\u0627\u0644\u0631\u064A\u0627\u0636\u0629 \u0648\u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0628\u062F\u0646\u064A", de: "Wassersport", en: "Swimming" },
