    titleTranslations: { ar: "\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u062D\u0631\u0643\u0629 \u0648\u0627\u0644\u0645\u0637\u0627\u0631\u062F\u0629 \u0641\u064A \u0633\u0627\u062D\u0629 \u0627\u0644\u0644\u0639\u0628", de: "Bewegungsspiele f\xFCr Kinder", en: "Playground Movement Games" },
    topic: "\u0627\u0644\u0631\u064A\u0627\u0636\u0629 \u0648\u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0628\u062F\u0646\u064A",
    topicTranslations: { ar: "\u0627\u0644\u0631\u064A\u0627\u0636\u0629 \u0648\u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0628\u062F\u0646\u064A", de: "Kinderspiele & Bewegung", en: "Playground Games" },
    grade: "\u0631\u0648\u0636\u0629 \u0648\u0623\u0637\u0641\u0627\u0644",
    level: "A1",
