    descriptionTranslations: { ar: "\u062D\u0631\u0643\u0627\u062A \u0627\u0644\u062A\u0648\u0627\u0632\u0646 \u0643\u0627\u0644\u062F\u0648\u0631\u0627\u0646 \u0648\u0627\u0644\u0627\u0646\u062D\u0646\u0627\u0621 \u0648\u0627\u0644\u0627\u0647\u062A\u0632\u0627\u0632.", de: "Balancieren, drehen, beugen, strecken, sch\xFCtteln.", en: "Balance, spin, bend, stretch, shake, stand still." },
